fn esseray_sn_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    if (ctx.var("Class").get()?.loosely_equals(&ctx.constant("JOB_SUPER_NOVICE_E")?)
        || ctx.var("Class").get()?.loosely_equals(&ctx.constant("JOB_SUPER_BABY_E")?))
    {
        ctx.lines_as(
            "Esseray",
            args!["You! Stronger than before.", "I knew you could pass the test~"],
        )?;
        ctx.close_window()?;
        return Err(Stop::End);
    }
    if ctx.var("BaseJob").get()?.loosely_equals(&ctx.constant("JOB_SUPER_NOVICE")?) {
        ctx.lines_as(
            "Esseray",
            args![
                "Hm? Hey, you're a member",
                "of our great Novice Society,",
                "aren't you? Isn't this the",
                "best club ever?!"
            ],
        )?;
        ctx.next()?;
        ctx.lines_as(
            "Essaray",
            args![
                "Living life mundanely,",
                "according to the principles",
                "of Mister Kimu-Shaun...",
                "It's great to be ordinary!"
            ],
        )?;
        ctx.next()?;
        ctx.lines_as(
            "Esseray",
            args![
                "Let's try to lead our lives",
                "as normally as we can!",
                "For your reference, I am",
                "the number one member,",
                "under Mister Tzerero of",
                "course!"
            ],
        )?;
        ctx.close_window()?;
        return Err(Stop::End);
    }
    if (ctx.var("BaseJob").get()?.loosely_equals(&ctx.constant("JOB_NOVICE")?) && ctx.var("Upper").get()? != 1) {
        ctx.lines_as(
            "Esseray",
            args![
                "Hah~ you don't know anything",
                "about being a normal person yet!",
                "Why don't you join our Novice",
                "Society? This club is the best in the world~"
            ],
        )?;
        ctx.next()?;
        ctx.lines_as(
            "Esseray",
            args!["Yup, Super Novices", "are the best characters!", "Hahahahahahahaha!"],
        )?;
        ctx.close_window()?;
        return Err(Stop::End);
    } else {
        ctx.lines_as(
            "Esseray",
            args![
                "Bah~! You're better than",
                "average...Hell, you may",
                "even be 'special.'",
                "What a shame! Well...",
                "I hope you still live",
                "your life positively."
            ],
        )?;
        ctx.close_window()?;
        return Err(Stop::End);
    }
}

